    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Konfigurer systemomfattende innstillinger: basis-URL, sikkerhet, standardspråk, tidssone, standardinnstillinger for risikoskåring og mer.',
    'SettingsPreferencesDesc'             => 'Standardverdier og atferdsinnstillinger på tvers av SimpleRisk: språk, tidssone, revisjonsstatuser, krav til risikokartlegging, brytere for brukergrensesnittatferd og lignende.',
    'SettingsFileUploadDesc'              => 'Tillatte filopplastingstyper og størrelsesgrenser for de ulike feltene for filvedlegg.',
    'SettingsMailDesc'                    => 'SMTP-konfigurasjon for utgående e-postvarsler, inkludert transport, vert, autentisering og svaradresse.',
    'SettingsBackupsDesc'                 => 'Konfigurer oppbevaring, tidsplan og nedlastingslenker for sikkerhetskopier av SimpleRisk-databasen.',
    'SettingsSecurityDesc'                => 'Innstillinger for autentisering, økt, passordpolicy, basis-URL og API-sikkerhet.',
    'SettingsLoggingDesc'                 => 'Konfigurasjon av feilsøkings- og revisjonslogging: loggnivåer, oppbevaring og plasseringen av loggfiler.',
    'HealthCheckDesc'                     => 'Diagnostiser systemstatus: PHP-versjon, utvidelser, filtillatelser, databasetilkobling, cron-tidsplan og aktiveringer av Extras.',
    'AnnouncementsDesc'                   => 'Skriv og administrer bannerkunngjøringer som er synlige for alle brukere.',
    'RegisterAndUpgradeDesc'              => 'Registrer SimpleRisk-installasjonen din, skriv inn eller forny en abonnementsnøkkel, og utløs Core/Extra-oppgraderinger med ett klikk.',
    'QueueMonitorDesc'                    => 'Inspiser bakgrunnsjobbkøen: ventende, pågående og mislykkede jobber.',
    'ExtrasDesc'                          => 'Aktiver, deaktiver og konfigurer SimpleRisk Extras (betalte tillegg).',
    'ArtificialIntelligenceExtraDesc'     => 'Ekstraprogrammet for kunstig intelligens gir forbedret risikoanalyse (inkludert FAIR-vurderinger) og tilpasset dokumentasjon.',
    'CustomizationExtraDesc'              => 'Customization Extra gjør det mulig å legge til og fjerne ulike typer felt og dynamisk opprette egendefinerte sidemaler.',
    'NotificationExtraDesc'               => 'Email Notification Extra gjør det mulig for SimpleRisk å sende e-postvarsler når risikoer sendes inn, endres eller på annen måte behandles. Denne Extra kan også legges til som et planlagt skript for å sende rutinemessige påminnelser når risikoer er klare for en ledelsesgjennomgang. I SimpleRisk Core-produktet, uten denne Extra, kommuniseres ingen varsler utenfor selve verktøyet.',
    'VulnerabilityManagementExtraDesc'    => 'Vulnerability Management Extra gir kunder mulighet til å integrere SimpleRisk-forekomsten sin med Qualys, Tenable.io eller Rapid7 Nexpose/InsightVM og importere både eiendels- og sårbarhetsdata til SimpleRisk. Derfra kan du velge hvilke områder du vil dekke, bestemme hvilke sårbarhetsskårer som skal importeres, og triagere hvilke sårbarheter som gjøres om til risikoer for å spore dem.',
    'IncidentManagementExtraDesc'         => 'Tillegget for hendelseshåndtering er basert på NIST 800-61-veiledningen for håndtering av hendelser i datasikkerhet og tilbyr hendelseshåndteringsfunksjoner fra SimpleRisk-systemet.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Gi nytt navn til SimpleRisk-terminologi (risiko, eiendel, rammeverk osv.) i hele brukergrensesnittet.',
    'RiskConfigurationDesc'               => 'Konfigurer regler for risikoscoring: nivåer, appetitt, SLA-terskler og de klassiske/bidragende risikoformlene.',
    'RiskAndThreatCatalogDesc'            => 'Vedlikehold katalogen over risiko- og trusselverdier som brukes i rullegardinmenyene.',
    'AddAndRemoveValuesDesc'              => 'Administrer rullegardinverdiene for risikofelt: plassering, kilde, kategori, team, teknologi og mer.',
    'AssetValuationDesc'                  => 'Konfigurer verdsettingsskalaen for eiendeler og overstyringer av verdsetting per eiendel.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Legg til, rediger, deaktiver og tilbakestill brukere; administrer passordpolicy.',
    'RoleManagementDesc'                  => 'Definer roller og tillatelsene hver rolle gir.',
    'TeamManagementDesc'                  => 'Opprett og administrer team som brukes til filtrering av postsynlighet.',
    'SeparationExtraDesc'                 => 'Ekstrafunksjonen Teambasert separasjon begrenser risikovisning til kun brukere som er medlemmer av teamet som risikoen er tilordnet. I SimpleRisk Core-produktet kan alle brukere se alle risikoer uten denne ekstrafunksjonen.',
    'CustomAuthenticationExtraDesc'       => 'Custom Authentication Extra gir støtte for Active Directory- og SAML-autentisering. I SimpleRisk Core-produktet, uten denne Extra, er det eneste alternativet å opprette nye brukere i SimpleRisks identitetsregister.',
    'EncryptionExtraDesc'                 => 'Encrypted Database Extra genererer en tilfeldig AES-256-bits krypteringsnøkkel og bruker den til å kryptere sensitiv tekst før den settes inn i SimpleRisk-databasen. Dette hindrer at noen kan vise eller endre dataene uten å bruke SimpleRisk-applikasjonen direkte.',
    'OrganizationManagementDesc'          => "Organisasjonshierarki-ekstraen gir muligheten til å definere flere forretningsenheter som kan inkludere et hvilket som helst antall team. Brukere kan deretter tilordnes ett eller flere team under ulike forretningsenheter. Dette påvirker en brukers mulighet til å se og bruke teamene, brukerne og ressursene de ikke er tilknyttet.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Masseslett risikoer. Bruk sparsomt – slettinger er permanente.',
    'AuditTrailDesc'                      => 'Søk i og eksporter systemrevisjonsloggen over brukerhandlinger.',
    'ImportExportExtraDesc'               => 'Import-Export Extra gir muligheten til å importere data til SimpleRisk ved å tilordne felt i en CSV-fil til felt i SimpleRisk-databasen. Den kan brukes til å importere revisjonsresultater fra et tredjeparts regneark, resultater fra sårbarhetsskanninger fra et annet verktøy, ressurser fra CMDB-en din og mer. Extra gir også muligheten til å eksportere CSV-filer fra SimpleRisk som inneholder risikoer, tiltak, gjennomganger eller en kombinasjonsrapport av alle tre.',
    'JiraExtraDesc'                       => 'Jira Integration Extra gir brukere mulighet til å integrere toveis med en Jira-forekomst. Den gjør det mulig å koble risikoer til Jira-saker, samt synkronisere data, status og kommentarer.',
    'APIExtraDesc'                        => 'API Extra lar kunder bruke et RESTful API til å opprette skriptbaserte interaksjoner med andre applikasjoner for å oppnå avansert automatisering og utnytte eksisterende infrastruktur.',
    'AdvancedSearchExtraDesc'             => 'Advanced Search Extra gjør søkefeltet i toppraden om til ett søk på tvers av risikoer, rammeverk, kontroller, dokumenter, unntak, tester, revisjoner, eiendeler og eiendelsgrupper, med en full søkeside for å arbeide gjennom resultatene. Den viser kun poster brukeren har tillatelse til å se.',
    'AssessmentsExtraDesc'                => 'Risk Assessment Extra gir brukere mulighet til å definere kontakter, opprette spørsmål (inkludert logikk), sette sammen flere spørsmål med en spørreskjemamal, opprette spørreskjemaer og sende dem til kontakter, se spørreskjemaresultatene, legge til risikoer basert på disse resultatene, sammenligne resultatene over tid, importere og eksportere eksternt tilpassede vurderinger, og gjennomgå revisjonssporet for risikovurderinger.',
    'ActiveAssessmentsDesc'               => 'Se og administrer vurderinger som for øyeblikket pågår.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra gir en visuell, hendelsesdrevet arbeidsflytmotor som automatiserer risikostyringshandlinger som svar på hendelser i SimpleRisk. Du kan utforme arbeidsflyter som utløses av endringer – for eksempel at en risiko sendes inn, oppdateres eller gjennomgås – for å rute godkjenninger, tilordne arbeid og holde prosessen i gang uten manuell inngripen.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra er en direkte integrasjon mellom Secure Controls Framework og SimpleRisk. Den importerer SCFs katalog over kontroller og deres tilordninger på tvers av et bredt spekter av samsvars- og cybersikkerhetsrammeverk til SimpleRisks styringsfunksjonalitet, slik at du kan ta i bruk rammeverkene du trenger og administrere kontrollene deres uten å måtte bygge dem manuelt.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migrer eldre varchar-kolonner for gjennomgangsdato til riktige datotyper. Vises bare når det er nødvendig.',
    'DatabaseUpgradeDesc'                 => 'Utløs SimpleRisk-databaseoppgraderingsrutinen manuelt.',

