    'SoaMissingFieldsTitle' => 'Denne erklæringen mangler detaljene på forsiden',
    'SoaMissingScopeStatement' => 'Ingen omfangserklæring er registrert for dette rammeverket. En anvendelighetserklæring bør angi omfanget den utarbeides for.',
    'SoaMissingInclusionJustification' => 'Ingen standard begrunnelse for inkludering er registrert. Aktuelle kontroller uten tilknyttede risikoer vil bruke en generisk erklæring i stedet for din egen.',
    'SoaEditFrameworkToAdd' => 'Legg dem til i rammeverket',

    // Opened from the Reporting Hub, which cannot supply a framework. A picker,
