    'SoaChooseFramework' => 'Velg et rammeverk',
    'SoaChooseFrameworkHint' => 'En anvendelighetserklæring utarbeides for ett rammeverk om gangen.',
    // The picker has a roster but nothing in it. Distinct from "this framework
