    'SoaFrameworkInactiveTitle' => 'Dette rammeverket er inaktivt',
    'SoaFrameworkInactiveBody' => 'En anvendelighetserklæring beskriver omfanget en organisasjon for øyeblikket opererer innenfor. Reaktiver rammeverket for å generere en.',
    'SoaFrameworkNotFoundBody' => 'Dette rammeverket finnes ikke lenger.',

    // A framework with no controls mapped into it. Not an error -- it is a real
