    'HowDoYouWantToAddAFramework' => 'Hvordan vil du legge til et rammeverk?',
    'CreateFrameworkManually' => 'Opprett ett manuelt',
    'CreateFrameworkManuallyHint' => 'Gi rammeverket et navn selv, og legg deretter til eller kartlegg kontrollene.',
    // Named for the framework rather than for its vendor. The hint was reworded
