    'AssetScoring' => 'Skåring av eiendeler',
    'AssetScoringSettingsHint' => 'Hver eiendel vurderes som Lav, Moderat eller Høy for konfidensialitet, integritet og tilgjengelighet, og konfidensialitet kan i stedet være Ikke relevant, noe som utelater den fra begge resultatene. Eiendelens FIPS-kategorisering er den høyeste av de tre vurderingene. Den vektede skåren er det vektede gjennomsnittet av de tre nivåverdiene, og intervallgrensene gjør denne skåren om til et Lavt, Moderat eller Høyt intervall. Hvis du endrer disse innstillingene, skåres alle eiendeler på nytt umiddelbart.',
